                if product_id:
                    product_counts[product_id] = product_counts.get(product_id, 0) + item.get('quantity', 1)

        # Sort by count
        sorted_products = sorted(product_counts.items(), key=lambda x: x[1], reverse=True)[:limit]

        # Get product details
        popular_products = []
        for product_id, count in sorted_products:
            product = db.query('products', id=product_id)
            if product['total'] > 0:
                popular_products.append({
